-- Hosted/ops seed: T Level weeks 1–3 progressive-release package (0.3.0).
-- Applied to linked project 2026-08-27. Package body only (catalogue already grounded).
-- Weeks are planned so Admin Post week & publish can release them one by one.
do $$
declare
  v_package jsonb;
  v_hash text;
  v_publication_id uuid;
  v_admin learning.teachers%rowtype;
begin
  select teacher.*
  into v_admin
  from learning.teachers as teacher
  where teacher.auth_user_id = 'fd5fcbfc-5c01-4df3-a8df-458e1dbb0cc4'
    and teacher.active;

  if not found then
    raise exception using errcode = 'P0001', message = 'PUBLICATION_SEED_ADMIN_MISSING';
  end if;

  v_package := $lp_pkg${"schema": "lp.content.package", "schemaVersion": "0.1.0", "id": "tlevel-software-development-content", "version": "0.3.0", "hub": {"schema": "lp.content.hub", "schemaVersion": "0.1.0", "id": "tlevel-software-development", "version": "0.1.0", "metadata": {"name": "T Level Digital Software Development Hub", "description": "T Level Digital Software Development learner hub."}, "relationships": {"curriculum": "tlevel-software-development-curriculum"}}, "curriculum": {"schema": "lp.content.curriculum", "schemaVersion": "0.1.0", "id": "tlevel-software-development-curriculum", "version": "0.1.0", "metadata": {"title": "T Level Digital Software Development", "course": "t-level-digital-software-development"}, "relationships": {"learningOutcomes": ["lo1", "lo2", "lo3", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems", "w2-research-emerging", "w2-evaluate-solutions", "w2-identify-gaps", "w3-business-scope", "w3-measurable-value", "w3-decomposition"], "assignments": ["os-formative"], "weeks": ["week-1", "week-2", "week-3"]}}, "learningOutcomes": [{"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "lo1", "version": "0.1.0", "metadata": {"title": "LO1: Analyse a problem to define requirements and acceptance criteria aligned to user needs (1.1 to 1.6)"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "lo2", "version": "0.1.0", "metadata": {"title": "LO2: Apply ethical principles and manage risks in line with legal and regulatory requirements (2.1 to 2.2)"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "lo3", "version": "0.1.0", "metadata": {"title": "LO3: Discover, evaluate and apply reliable sources of knowledge (3.1 to 3.2)"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w1-interpret-brief", "version": "0.1.0", "metadata": {"title": "Interpret a client request or project brief"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w1-research-market", "version": "0.1.0", "metadata": {"title": "Research the market environment, common problems and risks"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w1-investigate-systems", "version": "0.1.0", "metadata": {"title": "Investigate current hardware and software used in the context"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w2-research-emerging", "version": "0.1.0", "metadata": {"title": "Research newly emerging technologies"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w2-evaluate-solutions", "version": "0.1.0", "metadata": {"title": "Evaluate existing and potential solutions against user needs"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w2-identify-gaps", "version": "0.1.0", "metadata": {"title": "Identify guidelines, regulations and personal knowledge gaps"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w3-business-scope", "version": "0.1.0", "metadata": {"title": "Identify business requirements and define project scope"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w3-measurable-value", "version": "0.1.0", "metadata": {"title": "Assess measurable value to the user and client"}, "relationships": {}}, {"schema": "lp.content.learning-outcome", "schemaVersion": "0.1.0", "id": "w3-decomposition", "version": "0.1.0", "metadata": {"title": "Apply decomposition, pattern recognition and abstraction"}, "relationships": {}}], "assignments": [{"schema": "lp.content.assignment", "schemaVersion": "0.1.0", "id": "os-formative", "version": "0.1.0", "metadata": {"title": "Formative Occupational Specialism Areas 1 to 3 practice", "status": "available"}, "relationships": {"learningOutcomes": ["lo1", "lo2", "lo3"], "weeks": ["week-1", "week-2", "week-3"]}}], "weeks": [{"schema": "lp.content.week", "schemaVersion": "0.1.0", "id": "week-1", "version": "0.1.0", "metadata": {"teachingWeek": 1, "title": "Client Brief, Context and Initial Research", "status": "planned", "phase": "analyse-problem", "professionalPractice": "LO1 / 1.1 — interpret a client brief; research the market, problems and risks; investigate current hardware and software", "route": "weeks/week-1/", "weekCommencing": "2026-08-31", "releaseDate": null, "dueDate": null}, "relationships": {"curriculum": "tlevel-software-development-curriculum", "learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "sessions": ["week-1-lesson-1", "week-1-lesson-2", "week-1-lesson-3", "week-1-homework"]}}, {"schema": "lp.content.week", "schemaVersion": "0.1.0", "id": "week-2", "version": "0.1.0", "metadata": {"teachingWeek": 2, "title": "Emerging Technologies, Solutions and Knowledge Gaps", "status": "planned", "phase": "analyse-problem", "professionalPractice": "LO1 / 1.1 — research emerging technologies; evaluate existing and potential solutions; identify regulations and personal knowledge gaps", "route": "weeks/week-2/", "weekCommencing": "2026-09-07", "releaseDate": null, "dueDate": null}, "relationships": {"curriculum": "tlevel-software-development-curriculum", "learningOutcomes": ["lo1", "w2-research-emerging", "w2-evaluate-solutions", "w2-identify-gaps"], "assignment": "os-formative", "sessions": ["week-2-lesson-1", "week-2-lesson-2", "week-2-lesson-3", "week-2-homework"]}}, {"schema": "lp.content.week", "schemaVersion": "0.1.0", "id": "week-3", "version": "0.1.0", "metadata": {"teachingWeek": 3, "title": "Business Requirements, Scope and Decomposition", "status": "planned", "phase": "analyse-problem", "professionalPractice": "LO1 / 1.1 — identify business requirements and scope; assess measurable value; apply decomposition, pattern recognition and abstraction", "route": "weeks/week-3/", "weekCommencing": "2026-09-14", "releaseDate": null, "dueDate": null}, "relationships": {"curriculum": "tlevel-software-development-curriculum", "learningOutcomes": ["lo1", "w3-business-scope", "w3-measurable-value", "w3-decomposition"], "assignment": "os-formative", "sessions": ["week-3-lesson-1", "week-3-lesson-2", "week-3-lesson-3", "week-3-homework"]}}], "sessions": [{"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-1-lesson-1", "version": "0.1.0", "metadata": {"title": "Lesson 1: Annotating the client brief", "kind": "session", "summary": "Baseline diagnostic, then extract organisation, users, constraints, success measures and missing information from the Oakfield brief.", "sortOrder": 1, "defaultOpen": true}, "relationships": {"week": "week-1", "activities": ["week-1-lesson-1-retrieval", "week-1-lesson-1-main", "week-1-lesson-1-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-1-lesson-2", "version": "0.1.0", "metadata": {"title": "Lesson 2: Market, problems and risks", "kind": "session", "summary": "Research the market environment, typical problems and risks for adult-learning digital services.", "sortOrder": 2, "defaultOpen": false}, "relationships": {"week": "week-1", "activities": ["week-1-lesson-2-retrieval", "week-1-lesson-2-main", "week-1-lesson-2-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-1-lesson-3", "version": "0.1.0", "metadata": {"title": "Lesson 3: Current systems and exit check", "kind": "session", "summary": "Investigate hardware and software already in use, then list remaining research questions.", "sortOrder": 3, "defaultOpen": false}, "relationships": {"week": "week-1", "activities": ["week-1-lesson-3-retrieval", "week-1-lesson-3-main", "week-1-lesson-3-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-1-homework", "version": "0.1.0", "metadata": {"title": "Homework: one real digital product", "kind": "homework", "summary": "Find one real digital product and describe the problem it addresses, the likely client and the users it serves.", "sortOrder": 4, "defaultOpen": false}, "relationships": {"week": "week-1", "activities": ["week-1-homework-product"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-2-lesson-1", "version": "0.1.0", "metadata": {"title": "Lesson 1: Existing versus emerging options", "kind": "session", "summary": "Retrieve Week 1 findings, then compare an existing approach with an emerging alternative.", "sortOrder": 1, "defaultOpen": true}, "relationships": {"week": "week-2", "activities": ["week-2-lesson-1-retrieval", "week-2-lesson-1-main", "week-2-lesson-1-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-2-lesson-2", "version": "0.1.0", "metadata": {"title": "Lesson 2: Evaluate candidate solutions", "kind": "session", "summary": "Evaluate two or three candidates for Oakfield, including at least one emerging technology.", "sortOrder": 2, "defaultOpen": false}, "relationships": {"week": "week-2", "activities": ["week-2-lesson-2-retrieval", "week-2-lesson-2-main", "week-2-lesson-2-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-2-lesson-3", "version": "0.1.0", "metadata": {"title": "Lesson 3: Regulation and knowledge gaps", "kind": "session", "summary": "Identify guidelines or regulations that may apply, and list personal knowledge, skill or information gaps.", "sortOrder": 3, "defaultOpen": false}, "relationships": {"week": "week-2", "activities": ["week-2-lesson-3-retrieval", "week-2-lesson-3-main", "week-2-lesson-3-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-2-homework", "version": "0.1.0", "metadata": {"title": "Homework: one emerging technology with a source", "kind": "homework", "summary": "Research one emerging technology relevant to Oakfield. Note one benefit, one risk and one source.", "sortOrder": 4, "defaultOpen": false}, "relationships": {"week": "week-2", "activities": ["week-2-homework-emerging"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-3-lesson-1", "version": "0.1.0", "metadata": {"title": "Lesson 1: From research to scoped requirements", "kind": "session", "summary": "Turn a vague client statement into a scoped requirement, with in-scope, out-of-scope and unknown.", "sortOrder": 1, "defaultOpen": true}, "relationships": {"week": "week-3", "activities": ["week-3-lesson-1-retrieval", "week-3-lesson-1-main", "week-3-lesson-1-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-3-lesson-2", "version": "0.1.0", "metadata": {"title": "Lesson 2: Decomposition, patterns and abstraction", "kind": "session", "summary": "Break the Oakfield problem into parts, group similar needs and drop unnecessary detail.", "sortOrder": 2, "defaultOpen": false}, "relationships": {"week": "week-3", "activities": ["week-3-lesson-2-retrieval", "week-3-lesson-2-main", "week-3-lesson-2-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-3-lesson-3", "version": "0.1.0", "metadata": {"title": "Lesson 3: First-cut scope statement", "kind": "session", "summary": "Produce a first-cut scope statement and a simple decomposition for the continuing scenario.", "sortOrder": 3, "defaultOpen": false}, "relationships": {"week": "week-3", "activities": ["week-3-lesson-3-retrieval", "week-3-lesson-3-main", "week-3-lesson-3-formative"]}}, {"schema": "lp.content.session", "schemaVersion": "0.1.0", "id": "week-3-homework", "version": "0.1.0", "metadata": {"title": "Homework: rewrite two vague statements", "kind": "homework", "summary": "Rewrite two vague client statements as clearer business requirements and mark whether each is in scope.", "sortOrder": 4, "defaultOpen": false}, "relationships": {"week": "week-3", "activities": ["week-3-homework-rewrite"]}}], "activities": [{"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-retrieval", "version": "0.1.0", "metadata": {"title": "Baseline diagnostic: what a software project is for", "status": "available", "summary": "Record what you already know about clients, users and what a brief usually contains.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-1-retrieval", "estimatedDurationMinutes": 10, "activityType": "Diagnostic", "topics": ["Client", "Brief", "Users"], "detail": "Record what you already know about clients, users and what a brief usually contains."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-retrieval-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Baseline diagnostic", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-retrieval-intro", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "There are no marks for a 'right' baseline. This shows your starting point before we annotate a real brief."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-retrieval-purpose", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-1-retrieval:purpose", "sourceQuestionId": "purpose", "prompt": "In your own words, what is a software project for?", "placeholder": "A software project is for..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-retrieval-who", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-1-retrieval:who", "sourceQuestionId": "who", "prompt": "Who is a client, and how is a client different from a user?", "placeholder": "The client is... The users are..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-retrieval-q1", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "single-choice", "content": {"formative": true, "questionId": "week-1-lesson-1-retrieval:q1", "sourceQuestionId": "q1", "sourceType": "single", "prompt": "A local authority pays for a booking system that adult learners will use. Who is the client?", "options": [{"id": "a", "label": "Every adult learner who might book a course"}, {"id": "b", "label": "The local authority / Adult Skills Hub that requested the system"}, {"id": "c", "label": "The software tutor teaching this T Level"}, {"id": "d", "label": "Microsoft, because staff already use 365"}], "correctOptionId": "b", "feedback": {"correct": "The client is the organisation that requested the work. Learners are users, not the paying client.", "incorrect": "The client requested the work. Users are the people who will use the service."}}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main", "version": "0.1.0", "metadata": {"title": "Annotate a realistic client brief", "status": "available", "summary": "Watch how a brief is annotated, then mark organisation, users, constraints, success measures and gaps.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-1-main", "estimatedDurationMinutes": 35, "activityType": "Guided learning", "topics": ["Client brief", "Context", "Constraints"], "detail": "Watch how a brief is annotated, then mark organisation, users, constraints, success measures and gaps."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Interpreting the client request", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main-intro", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "Analysts do not start coding until they understand the client, the market and the current systems. A brief mixes stated needs, implied needs and missing information."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main-brief", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "callout", "content": {"title": "Continuing client: Oakfield Adult Skills Hub", "text": "Oakfield Adult Skills Hub is a local-authority adult education provider. It offers free and low-cost English, maths, digital-skills and vocational taster courses. Learners currently phone or visit reception. Staff keep a paper diary and a shared spreadsheet. Tutors take paper registers. Managers cannot see which courses are full until the end of the week. The client wants a digital service so learners can find a course and request a place, tutors can take a register, and managers can see attendance and produce funder reports. The service must work for people with low digital confidence, screen readers, and English as an additional language. Constraints include a limited budget, UK GDPR, some venues with weak Wi-Fi, and staff who already use Microsoft 365.", "tone": "info"}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main-extract-h", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "What to extract", "level": 3}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main-extract", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "Mark the organisation, who the users are, constraints (budget, law, buildings, existing tools), how success would be judged, and questions the brief does not answer. Stated needs are written down. Implied needs are reasonable but not spelled out — for example, a register that still works if Wi-Fi drops."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main-stated", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-1-main:stated", "sourceQuestionId": "stated", "prompt": "List three stated needs from the Oakfield brief.", "placeholder": "1. ... 2. ... 3. ...", "guidance": "Quote or closely paraphrase the brief."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main-missing", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-1-main:missing", "sourceQuestionId": "missing", "prompt": "List three research questions the brief does not answer.", "placeholder": "Question 1: ...", "guidance": "Good questions are specific: numbers, venues, funding rules, devices."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-main-teacher", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "teacher-note", "content": {"text": "SoL Week 1: baseline then tutor-modelled brief annotation. UDL: written, visual and verbal brief. Scaffold: annotation prompts. Challenge: assumptions the brief does not give."}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-formative", "version": "0.1.0", "metadata": {"title": "Progress check: client, user or context", "status": "available", "summary": "Distinguish client, user and context in short extracts.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-1-formative", "estimatedDurationMinutes": 10, "activityType": "Classification", "topics": ["Client", "User", "Context"], "detail": "Distinguish client, user and context in short extracts."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-formative-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Classify each statement", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-1-formative-sort", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "classification", "content": {"formative": true, "questionId": "week-1-lesson-1-formative:sort", "sourceQuestionId": "sort", "prompt": "Classify each statement from the Oakfield scenario.", "categories": [{"id": "client", "label": "Client / organisation"}, {"id": "user", "label": "User"}, {"id": "context", "label": "Context or constraint"}], "items": [{"id": "item-1", "label": "The local authority pays for the project", "correctCategoryId": "client"}, {"id": "item-2", "label": "An adult learner with a screen reader books a maths taster", "correctCategoryId": "user"}, {"id": "item-3", "label": "Some venues have weak Wi-Fi", "correctCategoryId": "context"}, {"id": "item-4", "label": "A tutor takes a register on a tablet in class", "correctCategoryId": "user"}, {"id": "item-5", "label": "Staff already use Microsoft 365", "correctCategoryId": "context"}, {"id": "item-6", "label": "Managers need funder reports", "correctCategoryId": "client"}]}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-retrieval", "version": "0.1.0", "metadata": {"title": "Retrieval: who the brief is about", "status": "available", "summary": "Retrieve client, users and constraints before looking at the wider market.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-2-retrieval", "estimatedDurationMinutes": 8, "activityType": "Retrieval", "topics": ["Client", "Users"], "detail": "Retrieve client, users and constraints before looking at the wider market."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-retrieval-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Retrieve the Oakfield context", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-retrieval-users", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-2-retrieval:users", "sourceQuestionId": "users", "prompt": "Name two user groups in the Oakfield brief besides managers.", "placeholder": "1. ... 2. ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-retrieval-q1", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "single-choice", "content": {"formative": true, "questionId": "week-1-lesson-2-retrieval:q1", "sourceQuestionId": "q1", "sourceType": "single", "prompt": "Which statement is a market-environment point rather than a single user need?", "options": [{"id": "a", "label": "Fatima uses a screen reader"}, {"id": "b", "label": "Other adult-learning providers already offer online enrolment"}, {"id": "c", "label": "The tutor wants a paper backup register"}, {"id": "d", "label": "The manager wants Friday reports"}], "correctOptionId": "b", "feedback": {"correct": "The market is other providers, products and expectations around the client, not one person's need.", "incorrect": "Market environment is the wider setting: competitors, typical products, regulation and public expectation."}}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-main", "version": "0.1.0", "metadata": {"title": "Research the market, problems and risks", "status": "available", "summary": "Use source cards to record typical problems and risks for this kind of service.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-2-main", "estimatedDurationMinutes": 35, "activityType": "Guided learning", "topics": ["Market research", "Risk", "Adult learning"], "detail": "Use source cards to record typical problems and risks for this kind of service."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-main-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Market environment and common risks", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-main-intro", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "A proposal is weak if it only repeats the client's words. Research what similar services do, what usually goes wrong, and who might be excluded."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-main-cards", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "callout", "content": {"title": "Source-card themes", "text": "Typical problems: duplicate bookings, no-shows, inaccessible forms, staff retyping paper registers, reports that do not match funder rules. Typical risks: personal data on shared spreadsheets, venues offline, learners who will not use an app-only service.", "tone": "info"}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-main-problem", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-2-main:problem", "sourceQuestionId": "problem", "prompt": "Describe one common problem for a booking-and-register service, and why it would matter to Oakfield.", "placeholder": "Problem: ... Why it matters: ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-main-risk", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-2-main:risk", "sourceQuestionId": "risk", "prompt": "Identify one risk if Oakfield stays on paper and spreadsheets.", "placeholder": "Risk: ... Who is affected: ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-main-teacher", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "teacher-note", "content": {"text": "SoL Week 1 guided learning: pairs research market, problems and risks using source cards. Reduce reading load with cards. Extension: who is missing from typical vendor case studies."}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-formative", "version": "0.1.0", "metadata": {"title": "Progress check: implied versus stated needs", "status": "available", "summary": "Mark whether extracts are stated, implied or not in the brief.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-2-formative", "estimatedDurationMinutes": 10, "activityType": "Classification", "topics": ["Stated needs", "Implied needs"], "detail": "Mark whether extracts are stated, implied or not in the brief."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-formative-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Stated, implied, or not in the brief", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-2-formative-sort", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "classification", "content": {"formative": true, "questionId": "week-1-lesson-2-formative:sort", "sourceQuestionId": "sort", "prompt": "Classify each need.", "categories": [{"id": "stated", "label": "Stated in the brief"}, {"id": "implied", "label": "Implied but not written"}, {"id": "absent", "label": "Not supported by the brief"}], "items": [{"id": "item-1", "label": "Learners should be able to request a place", "correctCategoryId": "stated"}, {"id": "item-2", "label": "The register should still work if Wi-Fi drops", "correctCategoryId": "implied"}, {"id": "item-3", "label": "The Hub wants a native iOS game", "correctCategoryId": "absent"}, {"id": "item-4", "label": "The service must follow UK GDPR", "correctCategoryId": "stated"}, {"id": "item-5", "label": "Funder reports should be possible without retyping", "correctCategoryId": "implied"}]}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-retrieval", "version": "0.1.0", "metadata": {"title": "Retrieval: problems and constraints", "status": "available", "summary": "Retrieve one problem and one constraint before investigating current systems.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-3-retrieval", "estimatedDurationMinutes": 8, "activityType": "Retrieval", "topics": ["Constraints", "Current systems"], "detail": "Retrieve one problem and one constraint before investigating current systems."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-retrieval-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Retrieve constraints", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-retrieval-constraint", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-3-retrieval:constraint", "sourceQuestionId": "constraint", "prompt": "Name two constraints from the Oakfield brief.", "placeholder": "1. ... 2. ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-retrieval-q1", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "single-choice", "content": {"formative": true, "questionId": "week-1-lesson-3-retrieval:q1", "sourceQuestionId": "q1", "sourceType": "single", "prompt": "Why investigate current hardware and software before proposing a new system?", "options": [{"id": "a", "label": "So you can copy a competitor's branding"}, {"id": "b", "label": "So the proposal fits what staff and venues already have"}, {"id": "c", "label": "So you can skip user research"}, {"id": "d", "label": "So coding can start on day one"}], "correctOptionId": "b", "feedback": {"correct": "Current tools, devices and venues shape what is realistic. A proposal that ignores them fails at go-live.", "incorrect": "Current systems are part of the context, not an optional extra."}}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-main", "version": "0.1.0", "metadata": {"title": "Research log: current hardware and software", "status": "available", "summary": "Record what Oakfield already uses and what that means for a new service.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-3-main", "estimatedDurationMinutes": 30, "activityType": "Independent application", "topics": ["Current systems", "Research log"], "detail": "Record what Oakfield already uses and what that means for a new service."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-main-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Current hardware and software", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-main-intro", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "Independent application: complete a structured research log. Sentence starters are allowed. Optional audio notes are fine if your centre agrees."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-main-starters", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "callout", "content": {"title": "Sentence starters", "text": "Staff currently... Learners currently... Devices in classrooms include... Data is stored in... This matters because...", "tone": "info"}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-main-hardware", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-3-main:hardware", "sourceQuestionId": "hardware", "prompt": "What hardware are staff and learners likely to use today, and what is uncertain?", "placeholder": "Staff: ... Learners: ... Uncertain: ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-main-software", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-3-main:software", "sourceQuestionId": "software", "prompt": "What software is already in the brief, and what must you still find out?", "placeholder": "Already known: ... Still unknown: ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-main-teacher", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "teacher-note", "content": {"text": "SoL Week 1 independent application: research log of current hardware/software. UDL: sentence starters and optional audio. Exit check: three remaining research questions."}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-formative", "version": "0.1.0", "metadata": {"title": "Exit check: three research questions", "status": "available", "summary": "Sort known systems from gaps, then list three questions you still need to answer before writing requirements.", "href": null, "difficulty": "standard", "familyId": "week-1-lesson-3-formative", "estimatedDurationMinutes": 10, "activityType": "Progress check", "topics": ["Research questions"], "detail": "Sort known systems from gaps, then list three questions you still need to answer before writing requirements."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-formative-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Exit check", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-formative-sort", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "classification", "content": {"formative": true, "questionId": "week-1-lesson-3-formative:sort", "sourceQuestionId": "sort", "prompt": "Classify each statement about Oakfield today.", "categories": [{"id": "current", "label": "Current system / already known"}, {"id": "unknown", "label": "Still unknown / needs research"}], "items": [{"id": "item-1", "label": "Staff keep a paper diary and a shared spreadsheet", "correctCategoryId": "current"}, {"id": "item-2", "label": "How many venues have reliable Wi-Fi", "correctCategoryId": "unknown"}, {"id": "item-3", "label": "Tutors take paper registers", "correctCategoryId": "current"}, {"id": "item-4", "label": "Whether waiting lists are required", "correctCategoryId": "unknown"}]}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-formative-q1", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-lesson-3-formative:q1", "sourceQuestionId": "q1", "prompt": "Write three research questions you still need to answer about Oakfield.", "placeholder": "1. ... 2. ... 3. ...", "guidance": "Each question should be answerable with evidence, not opinion."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-lesson-3-formative-q2", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "single-choice", "content": {"formative": true, "questionId": "week-1-lesson-3-formative:q2", "sourceQuestionId": "q2", "sourceType": "single", "prompt": "Which research question is most useful at this stage?", "options": [{"id": "a", "label": "Which colour scheme looks nicest?"}, {"id": "b", "label": "How many venues have reliable Wi-Fi, and what do tutors use if it fails?"}, {"id": "c", "label": "Should we use a trendy JavaScript framework?"}, {"id": "d", "label": "Which celebrity should appear in the app?"}], "correctOptionId": "b", "feedback": {"correct": "Useful questions close knowledge gaps that affect users, constraints and risk.", "incorrect": "Ask questions that change the proposal, not decoration."}}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-1-homework-product", "version": "0.1.0", "metadata": {"title": "Homework: one real digital product", "status": "available", "summary": "Find one real digital product and describe the problem it addresses, the likely client and the users it serves.", "href": null, "difficulty": "standard", "familyId": "week-1-homework-product", "estimatedDurationMinutes": 25, "activityType": "Independent study", "topics": ["Client", "Users", "Problem"], "detail": "Find one real digital product and describe the problem it addresses, the likely client and the users it serves."}, "relationships": {"learningOutcomes": ["lo1", "w1-interpret-brief", "w1-research-market", "w1-investigate-systems"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-homework-product-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Independent study", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-homework-product-intro", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "Choose a real public or education service (booking, benefits, learning, libraries). Do not invent a fictional start-up."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-homework-product-product", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-homework-product:product", "sourceQuestionId": "product", "prompt": "Name the product and the problem it addresses.", "placeholder": "Product: ... Problem: ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-1-homework-product-roles", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-1-homework-product:roles", "sourceQuestionId": "roles", "prompt": "Who is the likely client, and who are the users? Note one group who might be poorly served.", "placeholder": "Client: ... Users: ... Poorly served: ..."}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-retrieval", "version": "0.1.0", "metadata": {"title": "Retrieval: Oakfield context and current systems", "status": "available", "summary": "Retrieve client context and current systems before considering newer technologies.", "href": null, "difficulty": "standard", "familyId": "week-2-lesson-1-retrieval", "estimatedDurationMinutes": 8, "activityType": "Retrieval", "topics": ["Current systems", "Client context"], "detail": "Retrieve client context and current systems before considering newer technologies."}, "relationships": {"learningOutcomes": ["lo1", "w2-research-emerging", "w2-evaluate-solutions", "w2-identify-gaps"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-retrieval-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Retrieve Week 1", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-retrieval-now", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-2-lesson-1-retrieval:now", "sourceQuestionId": "now", "prompt": "What do Oakfield staff use today to take bookings and registers?", "placeholder": "Bookings: ... Registers: ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-retrieval-q1", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "single-choice", "content": {"formative": true, "questionId": "week-2-lesson-1-retrieval:q1", "sourceQuestionId": "q1", "sourceType": "single", "prompt": "A technology is 'emerging' in this project when:", "options": [{"id": "a", "label": "It is digital"}, {"id": "b", "label": "It is still developing or not yet a normal fit for this context"}, {"id": "c", "label": "A vendor advertised it this week"}, {"id": "d", "label": "It uses the cloud"}], "correctOptionId": "b", "feedback": {"correct": "Emerging is about development and adoption in context, not a marketing label.", "incorrect": "Something can be current in one sector and emerging in adult-learning admin."}}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-main", "version": "0.1.0", "metadata": {"title": "Compare existing and emerging solutions", "status": "available", "summary": "Use fitness for purpose, cost, risk, regulation and user impact — not personal preference.", "href": null, "difficulty": "standard", "familyId": "week-2-lesson-1-main", "estimatedDurationMinutes": 35, "activityType": "Guided learning", "topics": ["Evaluation", "Emerging technology"], "detail": "Use fitness for purpose, cost, risk, regulation and user impact — not personal preference."}, "relationships": {"learningOutcomes": ["lo1", "w2-research-emerging", "w2-evaluate-solutions", "w2-identify-gaps"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-main-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Comparing options", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-main-intro", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "Teams evaluate options before they write a proposal. An emerging tool is not automatically better."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-main-criteria", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "callout", "content": {"title": "Comparison criteria", "text": "Purpose and users; cost (including training); risk; regulation (GDPR, accessibility); user impact, including digital exclusion; vendor lock-in and maintainability.", "tone": "info"}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-main-compare", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-2-lesson-1-main:compare", "sourceQuestionId": "compare", "prompt": "Compare paper-plus-spreadsheet with one emerging alternative (for example AI course matching or biometric attendance). Use at least three criteria.", "placeholder": "Existing: ... Emerging: ... Criteria: ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-main-justify", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-2-lesson-1-main:justify", "sourceQuestionId": "justify", "prompt": "Why is your alternative emerging rather than established in this adult-learning context?", "placeholder": "It is emerging because..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-main-teacher", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "teacher-note", "content": {"text": "SoL Week 2: tutor models comparison. Prompts cover purpose, users, cost, risk, regulation. Extension: lock-in, accessibility, long-term maintainability."}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-2-lesson-1-formative", "version": "0.1.0", "metadata": {"title": "Progress check: evidence or preference", "status": "available", "summary": "Spot evaluations that use evidence rather than taste.", "href": null, "difficulty": "standard", "familyId": "week-2-lesson-1-formative", "estimatedDurationMinutes": 10, "activityType": "Classification", "topics": ["Evaluation"], "detail": "Spot evaluations that use evidence rather than taste."}, "relation