.."}}]}, {"schema": "lp.content.activity", "schemaVersion": "0.1.0", "id": "week-2-lesson-3-main", "version": "0.1.0", "metadata": {"title": "Guidelines, regulations and personal gaps", "status": "available", "summary": "List applicable rules and a short personal research plan.", "href": null, "difficulty": "standard", "familyId": "week-2-lesson-3-main", "estimatedDurationMinutes": 30, "activityType": "Independent application", "topics": ["GDPR", "Accessibility", "Training needs"], "detail": "List applicable rules and a short personal research plan."}, "relationships": {"learningOutcomes": ["lo1", "w2-research-emerging", "w2-evaluate-solutions", "w2-identify-gaps"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-3-main-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Rules and gaps", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-3-main-intro", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "You are not expected to be a lawyer. You are expected to name relevant guidelines and be honest about what you still need to learn."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-3-main-rules-note", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "callout", "content": {"title": "Likely starting points", "text": "UK GDPR and ICO guidance; Equality Act / accessibility of public digital services; centre acceptable-use and AI policies; funder data-quality rules.", "tone": "info"}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-2-lesson-3-main-rules", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-2-lesson-3-main:rules", "sourceQuestionId": "rules", "pr