ue", "w3-decomposition"], "assignment": "os-formative", "questions": [], "assets": [], "prerequisites": []}, "blocks": [{"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-3-homework-rewrite-title", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "heading", "content": {"text": "Independent study", "level": 2}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-3-homework-rewrite-intro", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "paragraph", "content": {"text": "Use these vague lines, or two from Oakfield: 'make it user-friendly' and 'put everything online'."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-3-homework-rewrite-one", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-3-homework-rewrite:one", "sourceQuestionId": "one", "prompt": "Rewrite statement 1 as a business requirement. In scope for increment 1? Yes/No and why.", "placeholder": "Requirement: ... In scope: ..."}}, {"schema": "lp.content.block", "schemaVersion": "0.1.0", "id": "week-3-homework-rewrite-two", "version": "0.1.0", "metadata": {}, "relationships": {}, "type": "short-response", "content": {"formative": true, "questionId": "week-3-homework-rewrite:two", "sourceQuestionId": "two", "prompt": "Rewrite statement 2 as a business requirement. In scope? Yes/No and why.", "placeholder": "Requirement: ... In scope: ..."}}]}], "questions": [], "assets": []}$lp_pkg$::jsonb;
  v_hash := encode(extensions.digest(v_package::text, 'sha256'), 'hex');

  select publication.id
  into v_publication_id
  from platform.curriculum_publications as publication
  where publication.hub_code = 'tlevel-software-development'
    and publication.course_key = 't-level-digital-software-development'
    and publication.package_version = '0.3.0';

  if v_publication_id is not null then
    return;
  end if;

  update platform.curriculum_publications
  set status = 'superseded'
  where hub_code = 'tlevel-software-development'
    and course_key = 't-level-digital-software-development'
    and status = 'published';

  insert into platform.curriculum_publications (
    hub_code, course_key, package_version, schema_version, source_package_version,
    status, package, content_hash, author, reviewer, publication_notes,
    published_by_auth_user_id, published_by_staff_reference
  ) values (
    'tlevel-software-development',
    't-level-digital-software-development',
    '0.3.0',
    '0.1.0',
    '0.1.0',
    'published',
    v_package,
    v_hash,
    'Week 1-3 catalogue for progressive release',
    'Curriculum review',
    'Publish weeks 1-3 as planned so Admin Post week & publish dropdown can release them. Package body only (catalogue already grounded).',
    v_admin.auth_user_id,
    v_admin.staff_reference
  )
  returning id into v_publication_id;
end
$$;
